#include "tca/runtime.h"

template <typename T>
__device__ static __forceinline__ T RedsplitkCombine0(T p0, T p1) {
  return (p0 + p1);
}

// Redsplitk: launch 100 CTAs x 64 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
// dynamic SMEM pool: 8 B (v0: disjoint offsets, zero reuse)
namespace {

__global__ void __launch_bounds__(64) Redsplitk(uint32_t d0, uint32_t d1, const float* __restrict__ lhs, float* __restrict__ out) {
  tca::rt::TensorView<const float, 2u> lhs_v(lhs, d0, d1);
  tca::rt::TensorView<float, 1u> out_v(out, d0);
  // dynamic SMEM pool (8 B): one pool, disjoint v0 offsets — the future RA pass overlaps them
  extern __shared__ __align__(16) char tca_smem[];

  tca::rt::KernelInfo kinfo;
  // LNT #0: d0=CTA(T=32,LoC=100) d1=thread/warp(T=32,LoC=2) dim=thread/warp(LoC=64) d1=sequential(T=32,LoC=1)
  {
    // CTA-space mapping (absolute LoC per dim: 100u — the factorization this nest remaps)
    tca::rt::GridMapping grid_map0(kinfo, 1u, 100u);
    // per-CTA thread-space mapping (absolute warp counts K per dim: 2u)
    tca::rt::ThreadMapping thread_map1(kinfo, 1u, 2u);
    auto c0 = 1024u;
    auto c1 = 512u;
    auto c2 = 0.0f;
    auto c3 = 0u;
    auto v0 = grid_map0.index(0u);
    auto c4 = 32u;
    auto v1 = (v0 * c4);
    auto c5 = 32u;
    auto c6 = 0u;
    auto v2 = thread_map1.index(0u);
    auto c7 = 32u;
    auto v3 = (v2 * c7);
    auto v4 = thread_map1.lane_id();
    auto c8 = 1u;
    auto v5 = (v4 + c8);
    auto c9 = 1u;
    auto v6 = (v5 * c9);
    auto c10 = 32u;
    // warp reduction — the combiner is runtime-owned; per-element brackets [Init → reduced-dim walks (Reduce(value)) → Combine]
    tca::rt::WarpReducer<float> reducer0(c2, RedsplitkCombine0, thread_map1, tca::rt::SmemView<float, 1u>(reinterpret_cast<float*>(tca_smem + 0u), 2u));
    // @d0 tile-between rounds — CTA, T=32, LoC=100 (map dim 0)
    for (auto d0_it0 = tca::rt::CtaIterator(grid_map0, 0u, 100u, 0u, 3200u, c0); d0_it0.Has(); d0_it0.Next()) {
      auto v7 = (v1 + d0_it0.Index());
      auto v8 = tca::rt::umin(v7, c0);
      auto v9 = (c0 - v8);
      auto v10 = tca::rt::umin(c5, v9);
      // @d0 walk — sequential, LoC=1
      for (auto d0_it1 = tca::rt::SeqIterator(0u, 1u, v10); d0_it1.Has(); d0_it1.Next()) {
        // per-element bracket opens (argument-free; re-initializes from the construction-time init)
        reducer0.Init();
        // @d1 tile-between rounds — thread/warp, T=32, LoC=2 (map dim 0)
        for (auto d1_it2 = tca::rt::ThrIterator(thread_map1, 0u, 2u, 0u, 64u, c1); d1_it2.Has(); d1_it2.Next()) {
          auto v11 = (v3 + d1_it2.Index());
          auto v12 = tca::rt::umin(v11, c1);
          auto v13 = (c1 - v12);
          auto v14 = tca::rt::umin(c10, v13);
          auto v15 = tca::rt::umin(v6, v14);
          auto c11 = 1u;
          // @d1 inside walk (tile elements) — T=32
          for (auto d1_it3 = tca::rt::SeqIterator((v4 * c11), 1u, v15); d1_it3.Has(); d1_it3.Next()) {
            auto v16 = (v11 + d1_it3.Index());
            auto v17 = lhs_v.Get((v7 + d0_it1.Index()), v16);
            reducer0.Reduce(v17);
          }
        }
        // per-element combine — every participant receives the element's final value
        auto v18 = reducer0.Combine();
        // single-owner store — the element's owner thread writes (R2/R3)
        if (thread_map1.is_first_in_cta()) {
          out_v.Set(v18, (v7 + d0_it1.Index()));
        }
      }
    }
  }
}

}  // namespace

void RedsplitkLaunch(const tca::Tensor<float, 2u>& lhs, tca::Tensor<float, 1u>& out, cudaStream_t tca_stream) {
  const uint32_t d0 = lhs.Dim(0u);
  const uint32_t d1 = lhs.Dim(1u);
  TCA_REQUIRE(out.Dim(0u) == d0, "out.Dim(0) must equal d0 (dim d0)");
  tca::rt::ValidateLaunch(dim3(100u, 1u, 1u), dim3(64u, 1u, 1u), 8u, 512u);
  Redsplitk<<<dim3(100u, 1u, 1u), dim3(64u, 1u, 1u), 8u, tca_stream>>>(d0, d1, lhs.Data(), out.Data());
  TCA_CUDA_CHECK(cudaGetLastError());
}
